BEGIN TRANSACTION;
CREATE TABLE campaigns (
	id INTEGER NOT NULL, 
	campaign_name VARCHAR NOT NULL, 
	agent VARCHAR NOT NULL, 
	script VARCHAR NOT NULL, 
	schedule_date VARCHAR NOT NULL, 
	schedule_time VARCHAR NOT NULL, 
	status VARCHAR NOT NULL, 
	created_at DATETIME NOT NULL, user_id INTEGER REFERENCES users(id), voicemail_detection JSON, 
	PRIMARY KEY (id)
);
